// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy, Bank} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(address actor) public {
        // actor must not be able to be the test contract itself or address(0)
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        // Deploy a Bank that advertises the correct token hash, and give it
        // the code needed to be treated as a contract by C's supportsToken check.
        NuBank caller = new NuBank();

        // Fund nothing needed (airDrop is not payable). Make sure the caller
        // account has no prior balance on c for this key: the reference requires
        // hasNoBalance, so this must be 0 to allow the airdrop. We deploy c
        // fresh in setUp, so its balance for any fresh address is 0.

        // Execute airDrop from the bank contract. It should succeed on the
        // reference C (correct token hash) and be rejected by the mutant.
        bool ok;
        try caller.drop(address(c)) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: for ANY Bank advertising the correct token hash,
        // the reference C accepts the airDrop and increases the caller's
        // tokenBalance by 20. The mutant rejects it, leaving the balance at 0.
        // (The airdrop can only be claimed once per caller because of
        // hasNoBalance, so the only observable is 0 vs 20 after one call.)
        assertTrue(ok && c.tokenBalance(address(caller)) == 20);
    }
}

// Minimal Bank that advertises the correct token hash, so it should be an
// admissible caller for the reference C. It also forwards the airdrop call
// to C so that msg.sender inside C is this contract.
contract NuBank {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }

    function drop(address target) external {
        ModifierEntrancy(target).airDrop();
    }
}
